import React, { useState, useEffect } from "react";
import { useParams } from "react-router-dom";
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  Tooltip,
  PieChart,
  Pie,
  Cell,
  Legend,
  ResponsiveContainer
} from "recharts";
import Header from "../../components/Header/Header";
import Footer from "../../components/Footer/Footer";
import "./completionpage.css";

interface Evaluation {
  question: string;
  difficulty: string;
  subject: string;
  subtopic: string;
  reference_answer: string;
  user_answer: string;
  explanation: string;
  grammar_score: number;
  cosine_similarity_score: number;
  keyword_score: number;
  llm_relevance_score: number;
  total_score: number;
  time_taken: number;
}

interface ChartData {
  subject?: string;
  total_score?: number;
  name?: string;
  value?: number;
}

const COLORS = ["#0088FE", "#00C49F", "#FFBB28", "#FF8042"];

const CompletionPage: React.FC = () => {
  const [evaluations, setEvaluations] = useState<Evaluation[]>([]);
  const [finalScore, setFinalScore] = useState<number>(0);
  const [message, setMessage] = useState<string>("");
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);
  const [totalTimeTaken, setTotalTimeTaken] = useState<number>(0);
  const [subjectPerformance, setSubjectPerformance] = useState<ChartData[]>([]);
  const [difficultyDistribution, setDifficultyDistribution] = useState<ChartData[]>([]);
  const [difficultyPerformance, setDifficultyPerformance] = useState<ChartData[]>([]);
  const { testid: paramTestId } = useParams();

  useEffect(() => {
    const fetchCompletionData = async () => {
      const storedTestId = localStorage.getItem("test_id");
      const testid = paramTestId || storedTestId;
      if (!testid) {
        setError("Test ID not found. Please try again.");
        setLoading(false);
        return;
      }
      try {
        const response = await fetch("http://localhost:5000/view_result", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ testid }),
        });
        const data = await response.json();
        if (response.ok) {
          setEvaluations(data.evaluations);
          setFinalScore(data.final_score);
          setMessage(data.overall_feedback);
          setTotalTimeTaken(data.total_time_taken);
          setSubjectPerformance(data.subject_performance);
          setDifficultyDistribution(data.difficulty_distribution);
          setDifficultyPerformance(data.difficulty_performance);
        } else {
          setError(data.error || "Failed to load completion data.");
        }
      } catch (err) {
        setError("Failed to load completion data.");
      } finally {
        setLoading(false);
      }
    };
    fetchCompletionData();
  }, [paramTestId]);

  const formatOverallFeedback = (feedback: string) => {
    const sections = feedback.split("**");
    return sections.map((section, index) => {
      if (section.trim() === "") return null;
      return (
        <div key={index} className="feedback-section">
          <h4>{section.trim()}</h4>
          <p>{sections[index + 1]?.trim()}</p>
        </div>
      );
    });
  };

  const getSubjectColor = (subject: string) => {
    const colors: Record<string, string> = {
      "Computer Networks": "#8884d8",
      "Data Structures": "#82ca9d",
      "Operating Systems": "#ffc658",
      "Database Systems": "#ff8042",
      "Object Oriented Programming": "#0088FE"
    };
    return colors[subject] || "#" + Math.floor(Math.random()*16777215).toString(16);
  };

  if (loading) return <div className="loading">Loading...</div>;
  if (error) return <div className="error">{error}</div>;

  return (
    <div className="App">
      <Header />
      <div className="cmain-content two-column-layout">
        <div className="charts-column">
          <h2>Performance Analysis</h2>
          
          {/* Subject Performance Chart */}
          <div className="chart-container">
            <h3>Subject Performance</h3>
            <ResponsiveContainer width="100%" height={300}>
              <BarChart data={subjectPerformance}>
                <XAxis dataKey="subject" />
                <YAxis domain={[0, 100]} />
                <Tooltip />
                <Bar dataKey="total_score">
                  {subjectPerformance.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={getSubjectColor(entry.subject || "")} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>

          {/* Difficulty Distribution Chart */}
          <div className="chart-container">
            <h3>Difficulty Distribution</h3>
            <ResponsiveContainer width="100%" height={300}>
              <PieChart>
                <Pie
                  data={difficultyDistribution}
                  cx="50%"
                  cy="50%"
                  outerRadius={80}
                  fill="#8884d8"
                  dataKey="value"
                  label={({ name, percent }) => `${name}: ${(percent * 100).toFixed(0)}%`}
                >
                  {difficultyDistribution.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                  ))}
                </Pie>
                <Tooltip />
                <Legend />
              </PieChart>
            </ResponsiveContainer>
          </div>

          {/* Difficulty Performance Chart */}
          <div className="chart-container">
            <h3>Performance by Difficulty</h3>
            <ResponsiveContainer width="100%" height={300}>
              <BarChart data={difficultyPerformance}>
                <XAxis dataKey="name" />
                <YAxis domain={[0, 100]} />
                <Tooltip />
                <Bar dataKey="value">
                  {difficultyPerformance.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="evaluations-column">
          <div className="overall-feedback">
            <h2>Test Results</h2>
            <div className="score-display">
              <h3>Overall Score: {finalScore}%</h3>
              <h4>Total Time Taken: {totalTimeTaken} minutes</h4>
            </div>
            {formatOverallFeedback(message)}
          </div>

          {evaluations.map((evaluation, index) => (
            <div key={index} className="evaluation">
              <div className="question-header">
                <span className="subject" style={{ 
                  backgroundColor: getSubjectColor(evaluation.subject)
                }}>
                  {evaluation.subject}
                </span>
                <span className="difficulty" style={{
                  backgroundColor:
                    evaluation.difficulty?.toLowerCase() === "easy" ? "green" :
                    evaluation.difficulty?.toLowerCase() === "hard" ? "red" : "orange"
                }}>
                  {evaluation.difficulty || "Unknown"}
                </span>
              </div>
              
              <h4>Question {index + 1}: {evaluation.question}</h4>
              <div className="answer-section">
                <div>
                  <h5>Your Answer:</h5>
                  <p>{evaluation.user_answer}</p>
                </div>
                {evaluation.reference_answer && (
                  <div>
                    <h5>Reference Answer:</h5>
                    <p>{evaluation.reference_answer}</p>
                  </div>
                )}
              </div>
              
              <div className="scores-grid">
                <div className="score-item">
                  <span>Grammar</span>
                  <span>{evaluation.grammar_score}</span>
                </div>
                <div className="score-item">
                  <span>Relevance</span>
                  <span>{evaluation.llm_relevance_score}</span>
                </div>
                <div className="score-item">
                  <span>Keywords</span>
                  <span>{evaluation.keyword_score}</span>
                </div>
                <div className="score-item">
                  <span>Similarity</span>
                  <span>{evaluation.cosine_similarity_score}</span>
                </div>
                <div className="score-item total">
                  <span>Total</span>
                  <span>{evaluation.total_score}</span>
                </div>
                <div className="score-item">
                  <span>Time</span>
                  <span>{evaluation.time_taken} min</span>
                </div>
              </div>
              
              <div className="explanation">
                <h5>Feedback:</h5>
                <p>{evaluation.explanation}</p>
              </div>
              <hr />
            </div>
          ))}
        </div>
      </div>
      <Footer />
    </div>
  );
};

export default CompletionPage;
